export const SOFTWARE='Luma Studio — Larx Vo — vovinhlac.com';
const encoder=new TextEncoder(),crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
export function crc32(a){let crc=0xffffffff;for(const v of a)crc=crcTable[(crc^v)&255]^(crc>>>8);return(crc^0xffffffff)>>>0;}
function chunk(name,data){const out=new Uint8Array(data.length+12),v=new DataView(out.buffer);v.setUint32(0,data.length);out.set(encoder.encode(name),4);out.set(data,8);v.setUint32(out.length-4,crc32(out.subarray(4,out.length-4)));return out;}
export function pngResolution(bytes,dpi=300){const signature=[137,80,78,71,13,10,26,10];if(!signature.every((v,i)=>bytes[i]===v))throw Error('Invalid PNG.');const parts=[bytes.subarray(0,8)],density=new Uint8Array(9),view=new DataView(density.buffer);view.setUint32(0,Math.round(dpi/.0254));view.setUint32(4,Math.round(dpi/.0254));density[8]=1;let p=8,inserted=false;
 while(p<bytes.length){if(p+12>bytes.length)throw Error('Truncated PNG.');const n=new DataView(bytes.buffer,bytes.byteOffset+p,4).getUint32(0);if(p+n+12>bytes.length)throw Error('Truncated PNG chunk.');const name=String.fromCharCode(...bytes.subarray(p+4,p+8));if(!inserted&&name==='IDAT'){parts.push(chunk('pHYs',density),chunk('tEXt',encoder.encode('Software\0'+SOFTWARE.replace(/—/g,'-'))));inserted=true;}if(name!=='pHYs'&&!(name==='tEXt'&&new TextDecoder().decode(bytes.subarray(p+8,p+8+n)).startsWith('Software\0')))parts.push(bytes.subarray(p,p+n+12));p+=n+12;}
 if(!inserted)throw Error('PNG has no image data.');return parts;
}
export function jpegResolution(bytes,dpi=300){if(bytes[0]!==255||bytes[1]!==216)throw Error('Invalid JPEG.');const density=new Uint8Array([255,224,0,16,74,70,73,70,0,1,2,1,dpi>>8,dpi&255,dpi>>8,dpi&255,0,0]);const parts=[bytes.subarray(0,2),density],comment=encoder.encode(SOFTWARE.replace(/—/g,'-'));parts.push(new Uint8Array([255,254,(comment.length+2)>>8,(comment.length+2)&255]),comment);let p=2;
 while(p<bytes.length){if(bytes[p]!==255)throw Error('Invalid JPEG marker.');const marker=bytes[p+1];if(marker===218||marker===217){parts.push(bytes.subarray(p));break;}if(p+4>bytes.length)throw Error('Truncated JPEG.');const n=bytes[p+2]*256+bytes[p+3];if(n<2||p+2+n>bytes.length)throw Error('Truncated JPEG segment.');const jfif=marker===224&&String.fromCharCode(...bytes.subarray(p+4,p+9))==='JFIF\0';if(!jfif)parts.push(bytes.subarray(p,p+n+2));p+=n+2;}return parts;
}
export async function withPrintMetadata(blob,dpi=300){if(!Number.isInteger(dpi)||dpi<1||dpi>2400)throw Error('DPI phải từ1 đến2400.');const bytes=new Uint8Array(await blob.arrayBuffer());if(blob.type==='image/png')return new Blob(pngResolution(bytes,dpi),{type:blob.type});if(blob.type==='image/jpeg')return new Blob(jpegResolution(bytes,dpi),{type:blob.type});return blob;}
export const printSize=(w,h,dpi)=>`${(w/dpi*2.54).toFixed(2)} × ${(h/dpi*2.54).toFixed(2)} cm · ${dpi} DPI`;
